{"path":"assets/css/styles.css","content":"/* Earthy warm styles - organic shapes, friendly cards */
:root{
  --bg:#fbf7f2;
  --muted:#8a6f57;
  --accent:#b76a3a;
  --accent-2:#d9a26a;
  --card:#fff6ef;
  --text:#2f2b28;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial;line-height:1.5;color:var(--text);background:var(--bg)}
.container{max-width:980px;margin:0 auto;padding:24px}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:16px}
.brand{display:flex;align-items:center;gap:12px}
.avatar{width:56px;height:56px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));padding:8px}
.brand-title{margin:0;font-size:1.1rem}
.brand-sub{margin:0;color:var(--muted);font-size:0.9rem}
.nav ul{list-style:none;margin:0;padding:0;display:flex;gap:12px;align-items:center}
.nav a{color:var(--text);text-decoration:none;padding:8px 10px;border-radius:6px}
.btn-primary{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;text-decoration:none;display:inline-block}
.btn-secondary{background:transparent;border:2px solid var(--accent);color:var(--accent);padding:8px 12px;border-radius:8px}
.btn-ghost{background:transparent;border:1px solid transparent;color:var(--muted)}
.mobile-toggle{display:none}

/* Hero */
.hero{padding-top:36px;padding-bottom:36px}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:20px;align-items:center}
.eyebrow{color:var(--muted);margin:0 0 8px}
.hero-title{margin:0 0 12px;font-size:1.6rem}
.lead{color:#4a453f;margin:0 0 16px}
.hero-ctas{display:flex;gap:10px;margin-bottom:12px}
.quick-list{list-style:none;padding:0;margin:0;color:var(--muted);display:flex;gap:12px;font-size:0.9rem}
.hero-visual img{width:100%;height:auto;border-radius:16px}

/* Values */
.values .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:12px}
.card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 2px 6px rgba(0,0,0,0.05)}
.section-title{margin:0 0 10px;font-size:1rem;color:var(--muted)}

/* Methods */
.method-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}
.method-grid h5{margin:0 0 8px}

/* Objections */
.qa-list details{background:#fff;padding:12px;border-radius:10px;margin-bottom:8px}
.qa-list summary{cursor:pointer;font-weight:600}

/* Testimonials */
.test-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
blockquote{background:#fff5ef;padding:14px;border-left:4px solid var(--accent);border-radius:8px;margin:0}

/* Lead magnet */
.lead-magnet{margin-top:20px;padding:18px;background:linear-gradient(180deg, #fff7f0, #fff6ef);border-radius:12px}
.lead-inner{display:flex;justify-content:space-between;align-items:center;gap:12px}
.lead-form{display:flex;gap:8px}
.lead-form input{padding:10px;border-radius:8px;border:1px solid #e6d6c9}

/* CTA */
.final-cta{margin:28px 0;padding:20px;background:var(--card);border-radius:12px;text-align:center}
.cta-buttons{display:flex;gap:12px;justify-content:center}

/* Footer */
.site-footer{padding:20px 0;background:transparent;color:var(--muted)}
.footer-grid{display:grid;grid-template-columns:1fr 1fr auto;gap:16px;align-items:start}
.small{font-size:0.85rem}
.legal{border-top:1px solid #efe5da;padding-top:12px;margin-top:12px}

/* Modal */
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(15,12,10,0.4)}
.modal[aria-hidden="false"]{display:flex}
.modal-content{background:white;padding:18px;border-radius:12px;width:90%;max-width:420px}
.modal-close{background:transparent;border:0;float:right}

/* Responsive */
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .values .cards{grid-template-columns:1fr}
  .method-grid{grid-template-columns:1fr}
  .test-grid{grid-template-columns:1fr}
  .nav{display:none}
  .mobile-toggle{display:inline-block}
}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactive behavior: mobile nav, modal, lead form
document.addEventListener('DOMContentLoaded',function(){
  var mobileToggle=document.getElementById('mobileToggle');
  var nav=document.querySelector('.nav');
  if(mobileToggle){
    mobileToggle.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!expanded));
      if(nav) nav.style.display = expanded ? 'none' : 'block';
    });
  }

  // Modal
  var openGuide = document.getElementById('openGuide');
  var guideModal = document.getElementById('guideModal');
  var closeModal = document.getElementById('closeModal');
  if(openGuide){
    openGuide.addEventListener('click',function(){
      guideModal.setAttribute('aria-hidden','false');
      document.getElementById('modalEmail').focus();
    });
  }
  if(closeModal){
    closeModal.addEventListener('click',function(){
      guideModal.setAttribute('aria-hidden','true');
    });
  }
  guideModal.addEventListener('click',function(e){
    if(e.target===guideModal){ guideModal.setAttribute('aria-hidden','true'); }
  });

  // Lead form / modal form simple handling
  function handleFormSubmit(e){
    e.preventDefault();
    var email = e.target.querySelector('input[type="email"]').value.trim();
    if(!email || !/^\S+@\S+\.\S+$/.test(email)){
      alert('Please enter a valid email.');
      return;
    }
    // Placeholder: in a real site this would POST to a server or mailing service.
    alert('Thanks — the guide will arrive shortly to ' + email + '.');
    // reset form fields
    e.target.reset();
    // close modal if present
    if(guideModal) guideModal.setAttribute('aria-hidden','true');
  }

  var leadForm = document.getElementById('leadForm');
  var modalForm = document.getElementById('modalForm');
  if(leadForm) leadForm.addEventListener('submit',handleFormSubmit);
  if(modalForm) modalForm.addEventListener('submit',handleFormSubmit);

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var id = this.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el){ e.preventDefault(); el.scrollIntoView({behavior:'smooth'}); }
    });
  });
});"} 
